<?php
require_once '../config.php';require_once '../includes/auth.php';require_admin();
$events=$conn->query("SELECT e.*,SUM(CASE WHEN r.status='confirmed' THEN 1 ELSE 0 END) registrations FROM events e LEFT JOIN registrations r ON r.event_id=e.id GROUP BY e.id ORDER BY e.event_date ASC");$users=(int)$conn->query("SELECT COUNT(*) c FROM users WHERE role='user'")->fetch_assoc()['c'];$regs=(int)$conn->query("SELECT COUNT(*) c FROM registrations WHERE status='confirmed'")->fetch_assoc()['c'];$event_count=(int)$conn->query('SELECT COUNT(*) c FROM events')->fetch_assoc()['c'];$page_title='Admin Dashboard';$asset_prefix='../';include '../includes/header.php'; ?>
<main class="page-shell admin-shell"><div class="welcome"><div><p class="eyebrow">ADMIN CONSOLE</p><h1>Event operations</h1><p>Manage the college fest schedule and monitor registrations.</p></div><a class="primary-btn" href="event_add.php">+ Add Event</a></div><div class="stats-grid three"><div class="stat-card"><span>Total Events</span><strong><?= $event_count ?></strong></div><div class="stat-card accent"><span>Registered Students</span><strong><?= $users ?></strong></div><div class="stat-card"><span>Confirmed Registrations</span><strong><?= $regs ?></strong></div></div><section class="table-card"><div class="section-heading"><div><p class="eyebrow">SCHEDULE</p><h2>Event management</h2></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Registrations</th><th>Actions</th></tr></thead><tbody><?php while($e=$events->fetch_assoc()): ?><tr><td><strong><?= h($e['title']) ?></strong><small><?= h($e['category']) ?></small></td><td><?= h(date('d M Y',strtotime($e['event_date']))) ?></td><td><?= h($e['venue']) ?></td><td><?= (int)$e['registrations'] ?> / <?= (int)$e['capacity'] ?></td><td class="actions"><a href="event_edit.php?id=<?= (int)$e['id'] ?>">Edit</a><form method="post" action="event_delete.php" onsubmit="return confirm('Delete this event and its registrations?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><button class="danger-link" type="submit">Delete</button></form></td></tr><?php endwhile; ?></tbody></table></div></section>
<section class="table-card"><div class="section-heading"><div><p class="eyebrow">REGISTRATION REPORT</p><h2>Recent participants</h2></div></div><?php $participants=$conn->query("SELECT u.name,u.email,e.title,r.status,r.registered_at FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id ORDER BY r.registered_at DESC LIMIT 10"); ?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Event</th><th>Status</th><th>Registered</th></tr></thead><tbody><?php while($p=$participants->fetch_assoc()): ?><tr><td><?= h($p['name']) ?></td><td><?= h($p['email']) ?></td><td><?= h($p['title']) ?></td><td><span class="status <?= h($p['status']) ?>"><?= h(ucfirst($p['status'])) ?></span></td><td><?= h(date('d M Y, g:i A',strtotime($p['registered_at']))) ?></td></tr><?php endwhile; ?></tbody></table></div></section></main><?php include '../includes/footer.php'; ?>
